class LfuCache {
  constructor(capacity) {
    this.capacity = capacity
    this.entries = new Map()
    this.buckets = new Map()
    this.minFreq = 0
  }

  addToBucket(key, freq) {
    if (!this.buckets.has(freq)) this.buckets.set(freq, new Set())
    this.buckets.get(freq).add(key)
  }

  touch(key, entry) {
    const bucket = this.buckets.get(entry.freq)
    bucket.delete(key)
    if (bucket.size === 0) {
      this.buckets.delete(entry.freq)
      if (this.minFreq === entry.freq) this.minFreq++
    }
    entry.freq++
    this.addToBucket(key, entry.freq)
  }

  get(key) {
    const entry = this.entries.get(key)
    if (!entry) return -1
    this.touch(key, entry)
    return entry.value
  }

  put(key, value) {
    const entry = this.entries.get(key)
    if (entry) {
      entry.value = value
      this.touch(key, entry)
      return
    }
    if (this.entries.size === this.capacity) {
      const bucket = this.buckets.get(this.minFreq)
      const victim = bucket.values().next().value
      bucket.delete(victim)
      if (bucket.size === 0) this.buckets.delete(this.minFreq)
      this.entries.delete(victim)
    }
    this.entries.set(key, { value, freq: 1 })
    this.addToBucket(key, 1)
    this.minFreq = 1
  }
}

function runLfuCache(capacity, ops) {
  const cache = new LfuCache(capacity)
  return ops.map(([op, key, value]) => (op === 'get' ? cache.get(key) : (cache.put(key, value), null)))
}

